WITH latest AS (SELECT * FROM inventory QUALIFY ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY quantity DESC, id) = 1), joined AS (SELECT src.*, p.launch_date FROM latest src JOIN products p ON src.product_id = p.id), metrics AS (SELECT *, MAX(quantity) OVER (PARTITION BY store_id, product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_max_quantity, MIN(quantity) OVER (PARTITION BY store_id, product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_min_quantity, AVG(quantity) OVER (PARTITION BY store_id, product_id ORDER BY quantity, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_avg_quantity FROM joined), with_windows AS (SELECT id, quantity, running_max_quantity, running_min_quantity, running_avg_quantity, NTILE(10) OVER (PARTITION BY store_id, product_id ORDER BY quantity, id) quantity_bucket, CUME_DIST() OVER (PARTITION BY product_id ORDER BY running_min_quantity DESC) running_min_quantity_cume_dist, NTILE(4) OVER (PARTITION BY store_id ORDER BY running_max_quantity DESC, id) running_max_quantity_bucket FROM metrics), valid AS (SELECT *, ROUND(running_min_quantity * 0.85, 2) running_min_quantity_scaled FROM with_windows WHERE running_min_quantity <= 100), totals AS (SELECT CASE WHEN running_min_quantity >= 202 THEN 'HIGH' ELSE 'LOW' END AS running_min_quantity_tier, CASE WHEN quantity >= 181 THEN 'PREMIUM' ELSE 'STANDARD' END AS quantity_tier, STDDEV_SAMP(quantity) AS quantity_stddev, APPROX_PERCENTILE(running_avg_quantity, ARRAY(0.25, 0.5, 0.75)) AS running_avg_quantity_quartiles, MIN(running_min_quantity_cume_dist) AS min_running_min_quantity_cume_dist FROM valid GROUP BY ROLLUP (CASE WHEN running_min_quantity >= 202 THEN 'HIGH' ELSE 'LOW' END, CASE WHEN quantity >= 181 THEN 'PREMIUM' ELSE 'STANDARD' END)) SELECT running_min_quantity_tier, quantity_tier, running_avg_quantity_quartiles, min_running_min_quantity_cume_dist FROM totals
